    def test_small_input(self):
        """Test the function with a small input of n = 5."""
        self.assertEqual(solution(5), ["1", "2", "Fizz", "4", "Buzz"])

    def test_single_input(self):
        """Test the function with an input of n = 1."""
        self.assertEqual(solution(1), ["1"])

    def test_fizz_only(self):
        """Test the function with an input of n = 3."""
        self.assertEqual(solution(3), ["1", "2", "Fizz"])

    def test_buzz_only(self):
        """Test the function with an input of n = 5."""
        self.assertEqual(solution(5), ["1", "2", "Fizz", "4", "Buzz"])

    def test_fizzbuzz_only(self):
        """Test the function with an input of n = 15, focusing on FizzBuzz."""
        self.assertEqual(solution(15)[-1], "FizzBuzz")

    def test_large_input(self):
        """Test the function with a larger input of n = 100."""
        result = solution(100)
        self.assertEqual(len(result), 100)
        self.assertEqual(result[-1], "Buzz")

    def test_invalid_input_type(self):
        """Test the function with a non-integer input."""
        with self.assertRaises(TypeError):
            solution("15")

    def test_edge_case_zero(self):
        """Test the function with an input of n = 0, which is outside the given constraints."""
        with self.assertRaises(ValueError):
            solution(0)

    def test_edge_case_negative(self):
        """Test the function with a negative input, which is outside the given constraints."""
        with self.assertRaises(ValueError):
            solution(-5)

