        """Test the function with a basic string."""
        self.assertEqual(solution("Hello World"), 8)

    def test_single_character_string(self):
        """Test the function with a single character string."""
        self.assertEqual(solution("a"), 1)

    def test_string_with_repeated_characters(self):
        """Test the function with a string containing repeated characters."""
        self.assertEqual(solution("Programming"), 8)

    def test_string_with_all_unique_characters(self):
        """Test the function with a string containing all unique characters."""
        self.assertEqual(solution("abcdefghijklmnopqrstuvwxyz"), 26)

    def test_string_with_no_unique_characters(self):
        """Test the function with a string containing no unique characters."""
        self.assertEqual(solution("aaaaaa"), 0)

    def test_empty_string(self):
        """Test the function with an empty string."""
        self.assertEqual(solution(""), 0)

    def test_string_with_mixed_case(self):
        """Test the function with a string containing mixed case characters."""
        self.assertEqual(solution("HeLlO"), 1)

    def test_string_with_numbers_and_punctuation(self):
        """Test the function with a string containing numbers and punctuation."""
        self.assertEqual(solution("Hello, World! 123"), 15)

    def test_large_string(self):
        """Test the function with a large string."""
        large_string = "a" * 500 + "b" * 200 + "c" * 300
        self.assertEqual(solution(large_string), 3)

