def solution(s: str) -> int:
    s = s.lower()
    vowels = set('aeiou')
    count = 0
    for i in range(len(s) - 1):
        if s[i].isalpha() and s[i + 1].isalpha():
            if (s[i] in vowels and s[i + 1] not in vowels) or (s[i] not in vowels and s[i + 1] in vowels):
                count += 1
    return count

