def solution(n: int) -> int:
    """
    This function calculates the nth Fibonacci number using recursion.

    Args:
    n (int): The position of the Fibonacci number to be calculated.

    Returns:
    int: The nth Fibonacci number.
    """

    # Check if n is within the given constraints
    if not isinstance(n, int) or n < 0 or n > 30:
        raise TypeError("Input must be an integer between 0 and 30.")

    # Base cases for the Fibonacci sequence
    if n == 0:
        return 0  # F(0) = 0
    elif n == 1:
        return 1  # F(1) = 1
    else:
        # Recursive case: F(n) = F(n-1) + F(n-2) for n > 1
        return solution(n-1) + solution(n-2)

