def solution(operations):
    stack = []
    res = []
    for operation in operations:
        if operation.startswith("Push"):
            _, num = operation.split()
            stack.append(int(num))
            res.append(None)
        elif operation == "Pop":
            if stack:
                res.append(stack.pop())
            else:
                res.append("Error: Stack is empty")
        elif operation == "Top":
            if stack:
                res.append(stack[-1])
            else:
                res.append("Error: Stack is empty")
        elif operation == "IsEmpty":
            res.append(not stack)
    return res

def solution(stack, operation):
    if operation.startswith("Push"):
        _, num = operation.split()
        stack.append(int(num))
        return None
    elif operation == "Pop":
        if stack:
            return stack.pop()
        else:
            return "Error: Stack is empty"
    elif operation == "Top":
        if stack:
            return stack[-1]
        else:
            return "Error: Stack is empty"
    elif operation == "IsEmpty":
        return not stack

