    if not isinstance(n, int):
        raise TypeError("Input must be an integer")

    # Check if n is within the specified range
    if n < 0:
        raise RecursionError("Input must be a non-negative integer")
    elif n > 12:
        raise ValueError("Input must be an integer between 0 and 12")

    # Base case: The factorial of 0 is defined as 1
    if n == 0:
        return 1

    # Recursive case: n! = n * (n-1)!
    else:
        # Call the function with a smaller input (n-1) and multiply the result by n
        return n * solution(n-1)

