def solution(nums, target):
    """
    Searches for a target value in a rotated sorted array.

    Args:
    nums (list): A sorted array that has been rotated at some pivot point.
    target (int): The value to be searched in the array.

    Returns:
    int: The index of the target value if found, -1 otherwise.
    """
    if not nums:
        return -1  # Edge case: Empty array

    left, right = 0, len(nums) - 1  # Initialize pointers for binary search

    while left <= right:
        mid = (left + right) // 2  # Calculate mid index

        if nums[mid] == target:
            return mid  # Target found, return its index

        # If the left half is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                # Target is in the left half, update right pointer
                right = mid - 1
            else:
                # Target is in the right half, update left pointer
                left = mid + 1
        # If the right half is sorted
        else:
            if nums[mid] < target <= nums[right]:
                # Target is in the right half, update left pointer
                left = mid + 1
            else:
                # Target is in the left half, update right pointer
                right = mid - 1

    return -1  # Target not found

