def solution(n):
    if n <= 0:
        raise ValueError("Input should be a positive integer")
    if n == 1:
        return 1
    if n == 2:
        return 2

    a, b = 1, 2
    for _ in range(3, n+1):
        a, b = b, a + b
    return b

