def solution(m, n):
    # Initialize a 2D array to store the number of unique paths to each cell
    dp = [[1]*n for _ in range(m)]

    # Fill in the rest of the dp array
    for i in range(1, m):
        for j in range(1, n):
            # The number of unique paths to a cell is the sum of the number of paths to the cell above it and the cell to its left
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    # The number of unique paths to the bottom-right corner is stored in dp[m-1][n-1]
    return dp[m-1][n-1]

