class TestUniqueCharacterCount(unittest.TestCase):
    def test_basic_unique_characters(self):
        """Test the function with a string containing unique characters."""
        self.assertEqual(solution("abc"), 3)

    def test_string_with_duplicates(self):
        """Test the function with a string containing duplicate characters."""
        self.assertEqual(solution("abca"), 2)

    def test_empty_string(self):
        """Test the function with an empty string."""
        self.assertEqual(solution(""), 0)

    def test_single_character_string(self):
        """Test the function with a string containing a single character."""
        self.assertEqual(solution("a"), 1)

    def test_string_with_all_same_characters(self):
        """Test the function with a string containing all the same characters."""
        self.assertEqual(solution("aaaa"), 0)

    def test_large_string(self):
        """Test the function with a large string."""
        large_string = "a" * 50000 + "b" * 20000 + "c" * 30000
        self.assertEqual(solution(large_string), 3)

    def test_string_with_mostly_unique_characters(self):
        """Test the function with a string containing mostly unique characters."""
        unique_string = "".join(chr(97 + i) for i in range(50))  # 50 unique lowercase letters
        self.assertEqual(solution(unique_string), 50)

    def test_long_string_with_repeated_and_unique_chars(self):
        """Test the function with a long string containing both repeated and unique characters."""
        s = "abcdefghijklmnopqrstuvwxyz"  # 26 unique characters
        s += s  # duplicate the string
        self.assertEqual(solution(s), 0)  # All characters are repeated

