def solution(s: str) -> int:
    """
    Counts the number of unique characters in a given string.

    A unique character is defined as a character that appears exactly once in the string.

    Parameters:
    s (str): The input string consisting of lowercase alphabetic characters.

    Returns:
    int: The count of unique characters in the input string.
    """
    char_frequency = {}

    for char in s:
        char_frequency[char] = char_frequency.get(char, 0) + 1

    return sum(1 for frequency in char_frequency.values() if frequency == 1)

