def solution(nums):
 """
 This function calculates the length of the longest alternating subsequence in a given array of integers.

 Args:
 nums (list): A list of integers.

 Returns:
 int: The length of the longest alternating subsequence.
 """

 if not nums:
 return 0

 max_len_pos = [1] * len(nums)
 max_len_neg = [1] * len(nums)

 for i in range(1, len(nums)):
 for j in range(i):
 if nums[i] > nums[j]:
 max_len_pos[i] = max(max_len_pos[i], max_len_neg[j] + 1)
 if nums[i] < nums[j]:
 max_len_neg[i] = max(max_len_neg[i], max_len_pos[j] + 1)

 return max(max(max_len_pos), max(max_len_neg))

