def solution(s):
    # Base case: if the string has only one character, return it as the only permutation
    if len(s) == 1:
        return [s]

    # Initialize an empty set to store unique permutations
    permutations = set()

    # For each character in the string
    for i, char in enumerate(s):
        # Get the remaining characters
        remaining = s[:i] + s[i+1:]

        # Recursively generate permutations for the remaining characters
        for perm in solution(remaining):
            # Add the current character to the beginning of each permutation
            permutations.add(char + perm)

    # Convert the set of permutations to a list and return it
    return list(permutations)

