    count_dict = {}

    # Base case: if the list is empty, return 0
    def recursive_count(nums):
        if not nums:
            return
        count_dict[nums[0]] = count_dict.get(nums[0], 0) + 1
        recursive_count(nums[1:])

    # Call the helper function to count occurrences
    recursive_count(nums)

    # Sum up the unique elements
    return sum(num for num, count in count_dict.items() if count == 1)

