def solution(nums):
    def recursive_count(nums, index, count_dict):
        if index == len(nums):
            return sum(num for num, count in count_dict.items() if count == 1)
        count_dict[nums[index]] = count_dict.get(nums[index], 0) + 1
        return recursive_count(nums, index + 1, count_dict)
    return recursive_count(nums, 0, {})

