        self.assertEqual(len(output), 40320)
        self.assertEqual(set(output), set(["".join(p) for p in get_permutations(input_str)]))

def get_permutations(string):
    if len(string) == 1:
        return [string]
    permutations = []
    for i, char in enumerate(string):
        rest = string[:i] + string[i+1:]
        for p in get_permutations(rest):
            permutations.append(char + p)
    return permutations

