def solution(n):
    """
    Generates a FizzBuzz sequence from 1 to n.

    Args:
    n (int): The upper limit of the sequence (1 <= n <= 10^3).

    Returns:
    list: A list of strings representing the FizzBuzz sequence from 1 to n.

    Raises:
    ValueError: If n is less than 1.
    """
    if not isinstance(n, int) or n < 1:
        raise ValueError("Input n must be an integer greater than or equal to 1")

    result = [] 
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0: 
            result.append("FizzBuzz") 
        elif i % 3 == 0:
            result.append("Fizz") 
        elif i % 5 == 0:
            result.append("Buzz") 
        else:
            result.append(str(i)) 

    return result

