def solution(nums, target):
    """
    Searches for a target element in a possibly rotated sorted array that may contain duplicates.

    Args:
    - nums: A list of integers representing the possibly rotated sorted array.
    - target: An integer representing the target element to search for.

    Returns:
    - The index of the target element if found, -1 otherwise.
    """
    if not nums:
        return -1  # Edge case: empty array

    left, right = 0, len(nums) - 1  # Initialize search boundaries

    while left <= right:
        mid = left + (right - left) // 2  # Calculate mid index

        if nums[mid] == target:
            return mid  # Target found, return its index

        # If the left half is sorted
        if nums[left] < nums[mid]:
            if nums[left] <= target < nums[mid]:
                # Target could be in the left half
                right = mid - 1  # Continue searching in the left half
            else:
                left = mid + 1  # Target must be in the right half
        # If the right half is sorted
        elif nums[left] > nums[mid]:
            if nums[mid] < target <= nums[right]:
                # Target could be in the right half
                left = mid + 1  # Continue searching in the right half
            else:
                right = mid - 1  # Target must be in the left half
        # If the left and mid elements are equal, we can't be sure which half is sorted
        else:
            # If the target is equal to the left element, we can safely move the left pointer
            if nums[left] == target:
                return left
            # Move the left pointer to the right to try and find a sorted half
            left += 1

    return -1  # Target not found

