def solution(nums):
    if not isinstance(nums, list) or len(nums) == 0 or not all(isinstance(num, int) for num in nums):
        if not isinstance(nums, list):
            raise ValueError("Input must be an array of integers")
        elif len(nums) == 0:
            return []
        else:
            raise ValueError("Input must be an array of integers")

    count_dict = {}
    for num in nums:
        count_dict[num] = count_dict.get(num, 0) + 1

    rare_elements = [num for num, count in count_dict.items() if count == 1]
    return sorted(rare_elements)

