    m, n = len(grid), len(grid[0])

    # Initialize the dp table with zeros
    dp = [[0]*n for _ in range(m)]

    # Base case: there is one way to reach the start position
    dp[0][0] = 1

    # Fill in the first row
    for i in range(1, n):
        if grid[0][i] == 0:
            dp[0][i] = dp[0][i-1]

