def solution(nums):
    # Create a dictionary to store the results of subproblems
    memo = {}

    def rob(i):
        # Base case: If we have reached or gone past the end of the array, return 0
        if i >= len(nums):
            return 0

        # If the result of the current subproblem is already in the memo, return it
        if i in memo:
            return memo[i]

        # Recursive case: Choose the maximum between robbing the current house and not robbing it
        # If we rob the current house, we cannot rob the next house, so we move to i + 2
        # If we do not rob the current house, we can rob the next house, so we move to i + 1
        rob_current = nums[i] + rob(i + 2)
        not_rob_current = rob(i + 1)

        # Store the result of the current subproblem in the memo
        memo[i] = max(rob_current, not_rob_current)

        return memo[i]

    # Start the recursion from the first house
    return rob(0)

