def solution(capacity, operations):
    queue = [None] * capacity
    front, rear, size = 0, 0, 0
    results = []

    for operation in operations:
        op_parts = operation.split("(")
        op = op_parts[0]

        if op == "enqueue":
            value = int(op_parts[1].split(")")[0])
            if size == capacity:
                continue
            else:
                queue[rear] = value
                rear = (rear + 1) % capacity
                size += 1
        elif op == "dequeue":
            if size == 0:
                continue
            else:
                results.append(queue[front])
                queue[front] = None
                front = (front + 1) % capacity
                size -= 1
        elif op == "is_empty":
            results.append(size == 0)
        elif op == "is_full":
            results.append(size == capacity)
        elif op == "peek":
            if size == 0:
                continue
            else:
                results.append(queue[front])

    return results

